func (this *Bitget) authenticateBody(ch chan ccxt.AsyncResult[*string], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	this.CheckRequiredCredentials()
	var url *string = this.SafeString(params, "url", "")
	var client ccxt.ClientInterface = this.Client(url)
	var messageHash string = "authenticated"
	var future any = client.(ccxt.ClientInterface).ReusableFuture(messageHash)
	var authenticated any = client.(ccxt.ClientInterface).SubscriptionSafe(messageHash)
	if authenticated == nil {
		var timestamp string = strconv.FormatInt(this.Seconds(), 10)
		var auth string = timestamp + "GET" + "/user/verify"
		var signature string = this.Hmac(this.Encode(auth), this.Encode(this.Secret), ccxt.Sha256, "base64")
		var operation string = "login"
		var request map[string]any = map[string]any{
			"op": operation,
			"args": []any{map[string]any{
				"apiKey":     this.ApiKey,
				"passphrase": this.Password,
				"timestamp":  timestamp,
				"sign":       signature,
			}},
		}
		var message map[string]any = this.Extend(request, params)
		this.Watch(url, messageHash, message, messageHash)
	}

	r := <-future.(*ccxt.Future).Await()
	if r.Err != nil {
		panic(r.Err)
	}
	var resolved *string
	switch resolvedBox := r.Value.(type) {
	case *string:
		resolved = resolvedBox
	case string:
		resolved = &resolvedBox
	default:
		_ = resolvedBox
	}
	ch <- ccxt.AsyncResult[*string]{Value: resolved}
	return nil
}
