func (this *Bitget) HandleErrorMessage(client any, message any) any {
	//
	//    { event: "error", code: 30015, msg: "Invalid sign" }
	//
	var event *string = this.SafeString(message, "event")

	{
		ret__ := func(this *Bitget) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Bitget) any {
						// catch block:
						if ccxt.IsInstance(e, ccxt.AuthenticationError) {
							var messageHash string = "authenticated"
							client.(ccxt.ClientInterface).Reject(e, messageHash)
							if client.(ccxt.ClientInterface).SubscriptionHas(messageHash) {
								client.(ccxt.ClientInterface).SubscriptionDel(messageHash)
							}
						} else {
							// Note: if error happens on a subscribe event, user will have to close exchange to resubscribe. Issue #19041
							client.(ccxt.ClientInterface).Reject(e)
						}
						return true

					}(this)
				}
			}()
			// try block:
			if event != nil && *event == "error" {
				var code *string = this.SafeString(message, "code")
				var feedback string = this.Id + " " + this.Json(message)
				this.ThrowExactlyMatchedException(ccxt.GetValue(this.Exceptions["ws"], "exact"), code, feedback)
				var msg *string = this.SafeString(message, "msg", "")
				this.ThrowBroadlyMatchedException(ccxt.GetValue(this.Exceptions["ws"], "broad"), msg, feedback)
				panic(ccxt.ExchangeError(feedback))
			}
			return false

		}(this)
		if ret__ != nil {
			return ret__
		}
		return nil
	}
}
func (this *Bitget) HandleMessage(client any, message any) {
	//
	//   {
	//       "action": "snapshot",
	//       "arg": { instType: 'SPOT', channel: "ticker", instId: "BTCUSDT" },
	//       "data": [
	//         {
	//           "instId": "BTCUSDT",
	//           "last": "21150.53",
	//           "open24h": "20759.65",
	//           "high24h": "21202.29",
	//           "low24h": "20518.82",
	//           "bestBid": "21150.500000",
	//           "bestAsk": "21150.600000",
	//           "baseVolume": "25402.1961",
	//           "quoteVolume": "530452554.2156",
	//           "ts": 1656408934044,
	//           "labeId": 0
	//         }
	//       ]
	//   }
	// pong message
	//    "pong"
	//
	// login
	//
	//     { event: "login", code: 0 }
	//
	// subscribe
	//
	//    {
	//        "event": "subscribe",
	//        "arg": { instType: 'SPOT', channel: "account", instId: "default" }
	//    }
	// unsubscribe
	//    {
	//        "op":"unsubscribe",
	//        "args":[
	//          {
	//            "instType":"USDT-FUTURES",
	//            "channel":"ticker",
	//            "instId":"BTCUSDT"
	//          }
	//        ]
	//    }
	//
	// uta
	//
	//     {
	//         "action": "snapshot",
	//         "arg": { "instType": "spot", topic: "ticker", symbol: "BTCUSDT" },
	//         "data": [
	//             {
	//                 "highPrice24h": "120255.61",
	//                 "lowPrice24h": "116145.88",
	//                 "openPrice24h": "118919.38",
	//                 "lastPrice": "119818.83",
	//                 "turnover24h": "215859996.272276",
	//                 "volume24h": "1819.756798",
	//                 "bid1Price": "119811.26",
	//                 "ask1Price": "119831.18",
	//                 "bid1Size": "0.008732",
	//                 "ask1Size": "0.004297",
	//                 "price24hPcnt": "0.02002"
	//             }
	//         ],
	//         "ts": 1753230479687
	//     }
	//
	// unsubscribe
	//
	//     {
	//         "event": "unsubscribe",
	//         "arg": {
	//             "instType": "spot",
	//             "topic": "kline",
	//             "symbol": "BTCUSDT",
	//             "interval": "1m"
	//         }
	//     }
	//
	if ccxt.IsString(message) {
		if ccxt.IsEqual(message, "pong") {
			this.HandlePong(client, message)
		}
		return
	}
	if this.HandleErrorMessage(client, message) == true {
		return
	}
	var content *string = this.SafeString(message, "message")
	if content != nil && *content == "pong" {
		this.HandlePong(client, message)
		return
	}
	var event *string = this.SafeString(message, "event")
	if event != nil && *event == "login" {
		this.HandleAuthenticate(client, message)
		return
	}
	if event != nil && *event == "subscribe" {
		this.HandleSubscriptionStatus(client, message)
		return
	}
	if event != nil && *event == "unsubscribe" {
		this.HandleUnSubscriptionStatus(client, message)
		return
	}
	var methods map[string]any = map[string]any{
		"ticker":           this.HandleTicker,
		"trade":            this.HandleTrades,
		"publicTrade":      this.HandleTrades,
		"fill":             this.HandleMyTrades,
		"order":            this.HandleOrder,
		"orders":           this.HandleOrder,
		"ordersAlgo":       this.HandleOrder,
		"orders-algo":      this.HandleOrder,
		"orders-crossed":   this.HandleOrder,
		"orders-isolated":  this.HandleOrder,
		"account":          this.HandleBalance,
		"position":         this.HandlePositions,
		"positions":        this.HandlePositions,
		"account-isolated": this.HandleBalance,
		"account-crossed":  this.HandleBalance,
		"kline":            this.HandleOHLCV,
	}
	var arg map[string]any = ccxt.SafeMapTyped(message, "arg")
	var topic *string = this.SafeString2(arg, "channel", "topic", "")
	var method any = this.SafeValue(methods, topic)
	if method != nil {
		ccxt.CallDynamically(method, client, message)
	}
	if strings.Index(*topic, "candle") >= 0 {
		this.HandleOHLCV(client, message)
	}
	if strings.Index(*topic, "books") >= 0 {
		this.HandleOrderBook(client, message)
	}
}
